import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Area,
  AreaChart,
} from 'recharts';

const MonthlyActiveUsersChart = ({ data = defaultData, title = 'Monthly Active Users' }) => {
  const handleTooltip = (props) => {
    const { active, payload } = props;
    if (!active || !payload || !payload.length) return null;

    const data = payload[0].payload;
    return (
      <div
        style={{
          backgroundColor: '#ffffff',
          border: '1px solid #e5e7eb',
          borderRadius: '6px',
          padding: '8px 12px',
          boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        }}
      >
        <p style={{ margin: '0 0 4px 0', fontSize: '14px', fontWeight: 600 }}>
          {data.month}
        </p>
        <p style={{ margin: 0, fontSize: '14px', color: '#1f2937' }}>
          {data.users.toLocaleString()} users
        </p>
      </div>
    );
  };

  return (
    <div
      style={{
        width: '100%',
        height: '400px',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <h2
        style={{
          margin: '0 0 16px 0',
          fontSize: '18px',
          fontWeight: 600,
          color: '#111827',
        }}
      >
        {title}
      </h2>
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={data} margin={{ top: 8, right: 16, left: 0, bottom: 0 }}>
          <defs>
            <linearGradient id="colorGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
            </linearGradient>
          </defs>
          <CartesianGrid
            strokeDasharray="0"
            stroke="#f3f4f6"
            vertical={false}
            style={{ pointerEvents: 'none' }}
          />
          <XAxis
            dataKey="month"
            stroke="#9ca3af"
            style={{ fontSize: '12px' }}
            axisLine={false}
            tickLine={false}
          />
          <YAxis
            stroke="#9ca3af"
            style={{ fontSize: '12px' }}
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => (value >= 1000 ? `${(value / 1000).toFixed(0)}k` : value)}
          />
          <Tooltip content={handleTooltip} />
          <Area
            type="monotone"
            dataKey="users"
            stroke="#3b82f6"
            strokeWidth={2}
            fill="url(#colorGradient)"
            dot={false}
            isAnimationActive={true}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
};

const defaultData = [
  { month: 'Jan', users: 2400 },
  { month: 'Feb', users: 3210 },
  { month: 'Mar', users: 2290 },
  { month: 'Apr', users: 2000 },
  { month: 'May', users: 2181 },
  { month: 'Jun', users: 2500 },
  { month: 'Jul', users: 2100 },
  { month: 'Aug', users: 2200 },
  { month: 'Sep', users: 2290 },
  { month: 'Oct', users: 2390 },
  { month: 'Nov', users: 2490 },
  { month: 'Dec', users: 2590 },
];

export default MonthlyActiveUsersChart;
